 private TextView orderOption(String name,String glyph,String value){TextView t=label(name,14);t.setGravity(Gravity.CENTER);t.setMinHeight(dp(48));t.setPadding(dp(8),dp(8),dp(8),dp(8));t.setCompoundDrawablesWithIntrinsicBounds(LudoIcons.drawable(this,glyph,TEXT,dp(16)),null,null,null);t.setCompoundDrawablePadding(dp(4));t.setContentDescription("Ordine: "+name);t.setOnClickListener(v->navigate("order",value));return t;}
 private String currentOrder(){String value=Uri.parse(lastSearchUrl).getQueryParameter("order");return "newest_first".equals(value)?value:"relevance";}
 private int currentPriceLimit(){try{String value=Uri.parse(lastSearchUrl).getQueryParameter("price_to");return value==null?0:new java.math.BigDecimal(value).movePointRight(2).intValueExact();}catch(RuntimeException invalid){return 0;}}
 private void syncExplorationControls(){boolean ready=!loading&&web!=null&&!rendererGone;relevant.setSelected(!"newest_first".equals(currentOrder()));newest.setSelected(!relevant.isSelected());for(TextView option:new TextView[]{relevant,newest}){option.setBackground(option.isSelected()?selectedCapsule():capsule());option.setEnabled(ready);option.setAlpha(ready?1f:.5f);}surpriseButton.setEnabled(ready);huntsButton.setEnabled(ready);int actual=currentPriceLimit();if(actual>0)priceLimitCents=actual;syncingControls=true;priceToggle.setChecked(actual>0);syncingControls=false;priceToggle.setEnabled(ready);priceValue.setText(java.math.BigDecimal.valueOf(priceLimitCents,2).stripTrailingZeros().toPlainString()+" €");priceMinus.setEnabled(ready&&actual>0&&priceLimitCents>500);pricePlus.setEnabled(ready&&actual>0&&priceLimitCents<9999900);priceMinus.setAlpha(priceMinus.isEnabled()?1f:.35f);pricePlus.setAlpha(pricePlus.isEnabled()?1f:.35f);}
 private android.graphics.drawable.Drawable selectedCapsule(){GradientDrawable shape=new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,new int[]{Color.rgb(111,77,216),Color.rgb(151,113,224)});shape.setCornerRadius(dp(24));return new RippleDrawable(ColorStateList.valueOf(Color.argb(65,255,255,255)),shape,null);}
 private void stepPrice(int delta){applyPriceLimit(Math.max(500,Math.min(9999900,priceLimitCents+delta)));}
 private void applyPriceLimit(int cents){if(closed||web==null||loading){syncExplorationControls();return;}Uri current=Uri.parse(lastSearchUrl);Uri.Builder b=current.buildUpon().clearQuery();for(String key:current.getQueryParameterNames())if(!"price_to".equals(key)&&!"page".equals(key))for(String value:current.getQueryParameters(key))b.appendQueryParameter(key,value);b.appendQueryParameter("page","1");if(cents>0)b.appendQueryParameter("price_to",java.math.BigDecimal.valueOf(cents,2).stripTrailingZeros().toPlainString());String url=b.build().toString();if(!VintedBrowserPolicy.allowedPage(url))return;loading=true;pageDrained=false;refreshStatus();web.loadUrl(url);}
 private void fromHunts(){if(closed||web==null||loading)return;java.util.Set<String> favorites=new java.util.TreeSet<>(getSharedPreferences("ludo_game_preferences_v1",MODE_PRIVATE).getStringSet("favorites",java.util.Collections.emptySet()));if(favorites.isEmpty()){Toast.makeText(this,"Salva un gioco con il cuore nelle tue Cacce",Toast.LENGTH_SHORT).show();return;}try{ingest.execute(()->{java.util.List<GameRecord> games=new java.util.ArrayList<>();boolean failed=false;try(DealDatabase lookup=new DealDatabase(getApplicationContext())){MarketStore store=new MarketStore(getApplicationContext(),lookup);for(String id:favorites){String normalized=GamePreferenceState.gameId(id);if(normalized==null)continue;GameRecord game=store.gameStatsByBggId(normalized);if(game!=null&&game.name!=null&&!game.name.trim().isEmpty()&&game.name.length()<=100)games.add(game);}}catch(RuntimeException error){failed=true;}final boolean failure=failed;runOnUiThread(()->{if(closed||isFinishing())return;if(failure||games.isEmpty()){Toast.makeText(this,failure?"Cacce non disponibili. Riprova.":"Nessun titolo disponibile nelle tue Cacce",Toast.LENGTH_SHORT).show();return;}android.app.Dialog dialog=sheet("Dalle mie cacce");LinearLayout box=sheetBody(dialog);for(GameRecord game:games)choice(box,LudoIcons.HEART,game.name,"Cerca su Vinted",()->{dialog.dismiss();loadExploration(game.name,currentOrder(),0,currentPriceLimit());});dialog.show();dialog.getWindow().setLayout(-1,-2);});});}catch(java.util.concurrent.RejectedExecutionException busy){Toast.makeText(this,"Sto salvando gli annunci. Riprova tra poco.",Toast.LENGTH_SHORT).show();}}
