 private static boolean samePage(String a,String b){try{return Uri.parse(a).buildUpon().fragment(null).build().equals(Uri.parse(b).buildUpon().fragment(null).build());}catch(Exception e){return false;}}
 private static int bound(int n){return Math.max(0,Math.min(1000000,n));}
 private void observeRoute(Uri uri){if(uri==null||!"https".equals(uri.getScheme())||!("www.vinted.it".equals(uri.getHost())||"vinted.it".equals(uri.getHost())))return;String path=uri.getPath();if(path==null||!path.startsWith("/api/"))return;path=path.replaceAll("[0-9]+","{id}").replaceAll("[^a-zA-Z0-9/{}_\\-]","_");if(path.length()>160)path=path.substring(0,160);synchronized(routes){if(routes.size()<20)routes.add(path);}}
 private String reportLocked(){int price=0,seller=0,publication=0,language=0;for(JSONObject item:items.values()){if(item.has("priceCents"))price++;if(item.has("sellerId"))seller++;if(item.has("publication"))publication++;if(item.has("language"))language++;}String routeSummary;synchronized(routes){routeSummary=routes.toString();}return "build=browser-engine-intake-v1;app="+BuildConfig.VERSION_NAME+";state="+state+";mode="+mode+";features="+supported+";capture="+enabled+";scope=currentPage;page="+pageNumber()+";pageObserved="+pageObserved+";pagePrices="+pagePrices+";acquiredUnique="+items.size()+";updated="+updates+";price="+price+";seller="+seller+";publication="+publication+";language="+language+";jsonOrInitial="+jsonItems+";dom="+domItems+";dropped="+dropped+";unknownShapes="+unknownShapes+";readErrors="+readErrors+";oversized="+oversized+";rejected="+rejected.get()+";extraRequestsByCapture=0;networkScope=capturer-only;catalogWrites="+persistedPageIds.size()+";intakeScope=currentPage;pageDrained="+pageDrained+";intakeError="+intakeError+";sellerCoverage=partial;routes="+routeSummary;}
