 private int pageNumber(){try{return Math.max(1,Math.min(10,Integer.parseInt(Uri.parse(navigationUrl).getQueryParameter("page"))));}catch(Exception ignored){return 1;}}
 private static boolean captureReady(boolean enabled,boolean pageDrained,int saved,int observed,int acquired,String error,boolean animating){return enabled&&pageDrained&&saved==observed&&acquired==observed&&error.isEmpty()&&!animating;}
 private boolean pageAdvanceReady(int saved,int size,boolean moving){return uiState==BrowserUiState.manualMatch||captureReady(enabled,pageDrained,saved,pageObserved,size,intakeError,moving);}
