  animateCount(saved);previous.setEnabled(supported&&catalog&&!loading&&!pageFailed&&pageNumber()>1);
  next.setEnabled(supported&&catalog&&!loading&&!pageFailed&&pageNumber()<10&&pageAdvanceReady(saved,size,countMotion!=null&&countMotion.isRunning()));
  previous.setAlpha(previous.isEnabled()?1f:.35f);next.setAlpha(next.isEnabled()?1f:.35f);
  pageIndicator.setText(pageNumber()+" di 10");pageIndicator.setContentDescription("Pagina "+pageNumber()+" di 10");
  controlsHost.setVisibility(uiState==BrowserUiState.exploreExpanded&&"SEARCH".equals(mode)?View.VISIBLE:View.GONE);layoutPagination();
  manualCard.setVisibility(uiState==BrowserUiState.manualMatch?View.VISIBLE:View.GONE);
