 private void cancelCount(){if(countMotion!=null){countMotion.removeAllListeners();countMotion.cancel();countMotion=null;}}
 private void animateCount(int target){if(counter==null)return;if(progressSummary!=null)progressSummary.setContentDescription(target+" annunci salvati nella pagina corrente");if(target==shownCount)return;if(countMotion!=null&&countMotion.isRunning()&&countTarget==target)return;cancelCount();if(!resumed||!android.animation.ValueAnimator.areAnimatorsEnabled()||target<shownCount){shownCount=target;counter.setText(String.valueOf(target));return;}android.animation.ValueAnimator motion=android.animation.ValueAnimator.ofInt(shownCount,target);countMotion=motion;countTarget=target;motion.setDuration(Math.min(800,Math.max(250,(target-shownCount)*8L)));motion.setInterpolator(new android.view.animation.AccelerateInterpolator());motion.addUpdateListener(a->{shownCount=(Integer)a.getAnimatedValue();counter.setText(String.valueOf(shownCount));});motion.addListener(new android.animation.AnimatorListenerAdapter(){@Override public void onAnimationEnd(android.animation.Animator a){if(countMotion!=motion)return;countMotion=null;shownCount=target;counter.setText(String.valueOf(target));counter.setContentDescription(target+" annunci salvati");refreshStatus();}});motion.start();}
